INSERT INTO `wp_posts` ( `ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(263, 3, '2026-04-06 18:23:25', '2026-04-06 18:23:25', '<!-- wp:create-block/hero-block {"button":{"text":"Rejoindre l’aventure","url":"","openInNewTab":false}} -->\n<div class="wp-block-create-block-hero-block"><div class="block hero-text-block"><div class="hero-text-block__content min-h-[60vh] gap-[70px] uk-container" uk-scrollspy="cls:uk-animation-fade" data-uk-parallax="y: 50vh; opacity: 1, 0;  start: 0; end: 10vh; blur: 0, 0, 20px; scale: 1, 0.5;"><div class="hero-text-block__body"><h1 class="title title--h1 rte rte--em-c-5"><small class="block"><span>Une <strong>Escouade</strong>, c\'est <em>plus qu\'une équipe</em> :</span></small><span>c\'est une aventure humaine</span></h1></div><div class="hero-text-block__footer flex justify-center"></div></div></div></div>\n<!-- /wp:create-block/hero-block -->\n\n<!-- wp:create-block/content-block {"background":"","headingText":""} -->\n<div class="wp-block-create-block-content-block"><div class="block bgi  edito-block"><div class="edito-block__content uk-container flex flex-col gap-[64px]"><div class="edito-block__header hidden"></div><div class="edito-block__body flex flex-col gap-[64px] sm:gap-[76px] md:gap-[88px] lg:gap-[100px]"><!-- wp:create-block/content-card {"bodyText":"\\u003cp\\u003eChez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.\\u003c/p\\u003e\\u003cp\\u003eBasée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.\\u003c/p\\u003e\\u003cp\\u003ePlus qu’un simple recrutement, nous créons de véritables escouades : des équipes soudées, humaines et performantes.\\u003c/p\\u003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-1.png","alt":"","id":30}} -->\n<div class="wp-block-create-block-content-card"><div class="block edito-card false"><div class="edito-card__content flex flex-col md:flex-row"><div class="edito-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-1.png" alt=""/></figure></div><div class="edito-card__body"><div class="content"><h2 class="title title--h3 c--1a"><span>Qui sommes-nous</span></h2><div class="text"><div><p>Chez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.</p><p>Basée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.</p><p>Plus qu’un simple recrutement, nous créons de véritables escouades : des équipes soudées, humaines et performantes.</p></div></div><div class="actions"><a class="btn c--4 bgc--1a btn-shadow-sm" href="#" title="Découvrir l\'Escouade"><span>Découvrir l\'Escouade</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div>\n<!-- /wp:create-block/content-card --></div></div></div></div>\n<!-- /wp:create-block/content-block -->\n\n<!-- wp:create-block/tech-block -->\n<div class="wp-block-create-block-tech-block"><div class="block bgi bgi--4 tech-slider-block"><div class="tech-slider-block__content uk-container" data-uk-slider="autoplay:true; pause-on-hover:true; autoplay-interval:5000; velocity:0"><div class="tech-slider-block__body overflow-x-hidden"><div class="card tech-slider-card uk-slider-items uk-child-width-1-1" data-uk-scrollspy="cls:uk-animation-scale-up; target: .tech-item,h2 em; delay: 35; repeat: true"><!-- wp:create-block/tech-card -->\n<div class="wp-block-create-block-tech-card"><div class="tech-slider-card__content"><div class="tech-slider-card__header flex flex-col md:flex-row justify-between px-[40px] md:items-center"><h2 class="title title--h2 rte rte--em-c-5 c--2"><span>Les technologies <em>Frontend</em><small>au coeur de nos réalisations</small></span></h2><ul class="nav flex gap-[10px] m-0 justify-start"><li><button class="btn c--4 bgc--1-2 btn-shadow-sm px-0 size-[48px] flex items-center justify-center" data-uk-slider-item="previous"><i class="es-icon-chevron-left"></i></button></li><li><button class="btn c--4 bgc--1-2 btn-shadow-sm px-0 size-[48px] flex items-center justify-center" data-uk-slider-item="next"><i class="es-icon-chevron-right"></i></button></li></ul></div><div class="tech-slider-card__body md:px-[10px] uk-child-width-1-1"><ul class="tech-list gap-[10px] gap-y-[20px] md:gap-y-[40px] lg:gap-y-[50px]"><!-- wp:create-block/tech-item {"logo":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-react-icon.png","alt":"","id":71},"name":"React"} -->\n<li class="wp-block-create-block-tech-item tech-item"><figure><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-react-icon.png" alt="React"/></div><figcaption><span>React</span></figcaption></figure></li>\n<!-- /wp:create-block/tech-item -->\n\n<!-- wp:create-block/tech-item {"logo":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-vue.js.png","alt":"","id":80},"name":"Vue.js"} -->\n<li class="wp-block-create-block-tech-item tech-item"><figure><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-vue.js.png" alt="Vue.js"/></div><figcaption><span>Vue.js</span></figcaption></figure></li>\n<!-- /wp:create-block/tech-item -->\n\n<!-- wp:create-block/tech-item {"logo":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-nodejs.png","alt":"","id":66},"name":"jQuery"} -->\n<li class="wp-block-create-block-tech-item tech-item"><figure><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-nodejs.png" alt="jQuery"/></div><figcaption><span>jQuery</span></figcaption></figure></li>\n<!-- /wp:create-block/tech-item -->\n\n<!-- wp:create-block/tech-item {"logo":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-ionic.png","alt":"","id":54},"name":"Ionic"} -->\n<li class="wp-block-create-b