INSERT INTO `wp_posts` ( `ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(456, 3, '2026-09-21 11:01:50', '2026-09-21 11:01:50', '<h1><small>Une <strong>Escouade</strong>, c\'est <em>plus qu\'une équipe</em> :</small>c\'est une aventure humaine</h1><a title="Rejoindre l’aventure" href="#je-cherche-un-job">Rejoindre l’aventure</a><p><!-- /wp:create-block/hero-block --><!-- wp:create-block/content-block {"background":"","headingText":""} --></p> <p><!-- wp:create-block/content-card {"bodyText":"u003cpu003eChez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.u003c/pu003eu003cpu003eBasée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.u003c/pu003eu003cpu003ePlus qu’un simple recrutement, nous créons de véritables escouades : des équipes soudées, humaines et performantes.u003c/pu003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-1.png","alt":"Équipe de développeurs et talents IT Escouade Madagascar travaillant sur des projets européens","id":30},"button":{"text":"Découvrir l\'Escouade","url":"","openInNewTab":false},"cardStyle":0} --></p><figure><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-1.png" alt="Équipe de développeurs et talents IT Escouade Madagascar travaillant sur des projets européens" /></figure><h2>Qui sommes-nous</h2><p>Chez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.</p><p>Basée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.</p><p>Plus qu’un simple recrutement, nous créons de véritables escouades : des équipes soudées, humaines et performantes.</p><p><!-- /wp:create-block/content-card --></p><p><!-- /wp:create-block/content-block --><!-- wp:create-block/tech-block --></p><p><!-- wp:create-block/tech-card --></p><h2>Les technologies <em>Frontend</em><small>au coeur de nos réalisations</small>