     <li>\n                    <button type="button" data-uk-slider-item="next" aria-label="Slide suivante">\n                    </button>\n                </li>\n            </ul>\n            <ul>\n                                                        <li>\n                        <figure>\n                                                                            <img width="93" height="56" src="http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-aws.png" alt="logo aws" decoding="async" />                                                                    \n                                                        <figcaption >Amazon Web Services</figcaption>\n                        </figure>\n                    </li>\n                                                        <li>\n                        <figure>\n                                                                            <img width="103" height="80" src="http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-azure.png" alt="logo azure" decoding="async" />                                                                    \n                                                        <figcaption >Microsoft Azure</figcaption>\n                        </figure>\n                    </li>\n                                                        <li>\n                        <figure>\n                                                                            <img width="90" height="80" src="http://escouade.localhost:8080/wp-content/uploads/2026/03/tech-logo-google_cloud_platform.png" alt="logo google cloud platform" decoding="async" />                                                                    \n                                                        <figcaption >Google Cloud Platform</figcaption>\n                        </figure>\n                    </li>\n                                                        <li>\n                        <figure>\n           